import android.app.Activityimport android.content.pm.PackageManagerimport android.location.Locationimport android.os.Buildimport android.util.Logimport androidx.annotation.RequiresApiimport androidx.core.app.ActivityCompatimport com.example.media_reels.Utils.AppContanstimport com.google.android.gms.location.*import io.flutter.plugin.common.BinaryMessengerimport io.flutter.plugin.common.MethodChannel@RequiresApi(Build.VERSION_CODES.N)class GeoLocation(private val activity: Activity, binaryMessenger: BinaryMessenger) {    private val methodChannel: MethodChannel =        MethodChannel(binaryMessenger, AppContanst.CHANNEL_APP_GEOLOCATION)    private lateinit var fusedLocationClient: FusedLocationProviderClient    private lateinit var locationRequest: LocationRequest    private lateinit var locationCallback: LocationCallback    init {        fusedLocationClient = LocationServices.getFusedLocationProviderClient(activity)        setupMethodChannel()        setupLocationRequest()    }    /** Thiết lập cấu hình yêu cầu vị trí */    private fun setupLocationRequest() {        locationRequest = LocationRequest.Builder(Priority.PRIORITY_HIGH_ACCURACY, 5000)            .setMinUpdateIntervalMillis(2000)            .build()        locationCallback = object : LocationCallback() {            override fun onLocationResult(locationResult: LocationResult) {                for (location in locationResult.locations) {                    sendLocationToFlutter(location)                    fusedLocationClient.removeLocationUpdates(this) // Dừng cập nhật sau khi lấy được vị trí                }            }        }    }    /** Kiểm tra & Yêu cầu quyền truy cập vị trí */    @RequiresApi(Build.VERSION_CODES.N)    fun requestPermissions() {        if (ActivityCompat.checkSelfPermission(activity, android.Manifest.permission.ACCESS_FINE_LOCATION)            != PackageManager.PERMISSION_GRANTED ||            ActivityCompat.checkSelfPermission(activity, android.Manifest.permission.ACCESS_COARSE_LOCATION)            != PackageManager.PERMISSION_GRANTED) {            ActivityCompat.requestPermissions(                activity,                arrayOf(                    android.Manifest.permission.ACCESS_FINE_LOCATION,                    android.Manifest.permission.ACCESS_COARSE_LOCATION                ),                REQUEST_LOCATION_PERMISSION            )        }    }    /** Lấy vị trí hiện tại */    private fun getLocation() {        if (ActivityCompat.checkSelfPermission(                activity,                android.Manifest.permission.ACCESS_FINE_LOCATION            ) != PackageManager.PERMISSION_GRANTED && ActivityCompat.checkSelfPermission(                activity,                android.Manifest.permission.ACCESS_COARSE_LOCATION            ) != PackageManager.PERMISSION_GRANTED        ) {            return        }        fusedLocationClient.lastLocation            .addOnSuccessListener { location: Location? ->                if (location != null) {                    sendLocationToFlutter(location)                } else {                    requestNewLocation()                }            }            .addOnFailureListener {                Log.e("GeoLocation", "Lỗi khi lấy vị trí: ${it.message}")            }    }    /** Gửi yêu cầu lấy vị trí mới nếu `lastLocation` là null */    private fun requestNewLocation() {        if (ActivityCompat.checkSelfPermission(                activity,                android.Manifest.permission.ACCESS_FINE_LOCATION            ) != PackageManager.PERMISSION_GRANTED && ActivityCompat.checkSelfPermission(                activity,                android.Manifest.permission.ACCESS_COARSE_LOCATION            ) != PackageManager.PERMISSION_GRANTED        ) {            return        }        fusedLocationClient.requestLocationUpdates(locationRequest, locationCallback, null)    }    /** Gửi vị trí về Flutter */    private fun sendLocationToFlutter(location: Location) {        val resultMap = mapOf(            "latitude" to location.latitude,            "longitude" to location.longitude        )        methodChannel.invokeMethod(AppContanst.METHOD_GET_GEOLOCATION, resultMap)    }    /** Thiết lập kênh Flutter */    @RequiresApi(Build.VERSION_CODES.N)    private fun setupMethodChannel() {        methodChannel.setMethodCallHandler { call, result ->            when (call.method) {                AppContanst.METHOD_PERMISSION_GEOLOCATION -> {                    requestPermissions()                    result.success(null)                }                AppContanst.METHOD_GET_GEOLOCATION -> {                    getLocation()                    result.success(null)                }                else -> {                    result.notImplemented()                }            }        }    }    companion object {        private const val REQUEST_LOCATION_PERMISSION = 1001    }}